arguments.command:
python3 - <<'PY'
p='src/solver.cpp';s=open(p).read();open('src/solver.backup','w').write(s)
pos=s.index('        for(auto& r:rs) {\n            bool changed=true;')
s=s[:pos]+r'''
        // Exchange route tails (2-opt*) and swap customers across routes.
        for(int pass=0;pass<2 && !expired();pass++) {
            double gain=-1e-6;int ba=-1,bb=-1;R ar,br;
            for(int a=0;a<(int)rs.size();a++)for(int b=a+1;b<(int)rs.size();b++) {
                const R& x=rs[a];const R& y=rs[b];
                for(int i=0;i<=(int)x.v.size();i++)for(int j=0;j<=(int)y.v.size();j++) {
                    int ap=i?x.v[i-1]:0,an=i<(int)x.v.size()?x.v[i]:0;
                    int bp=j?y.v[j-1]:0,bn=j<(int)y.v.size()?y.v[j]:0;
                    double g=d[ap][bn]+d[bp][an]-d[ap][an]-d[bp][bn];
                    bool empty=(i==0 && j==(int)y.v.size()) || (j==0 && i==(int)x.v.size());
                    if(empty)g-=2000;
                    if(g>=gain)continue;
                    R u,v;u.v.assign(x.v.begin(),x.v.begin()+i);u.v.insert(u.v.end(),y.v.begin()+j,y.v.end());
                    v.v.assign(y.v.begin(),y.v.begin()+j);v.v.insert(v.v.end(),x.v.begin()+i,x.v.end());
                    if(update(u)&&update(v)){gain=g;ba=a;bb=b;ar=std::move(u);br=std::move(v);}
                }
                for(int i=0;i<(int)x.v.size();i++)for(int j=0;j<(int)y.v.size();j++) {
                    int c=x.v[i],e=y.v[j],ap=i?x.v[i-1]:0,an=i+1<(int)x.v.size()?x.v[i+1]:0;
                    int bp=j?y.v[j-1]:0,bn=j+1<(int)y.v.size()?y.v[j+1]:0;
                    double g=d[ap][e]+d[e][an]+d[bp][c]+d[c][bn]-d[ap][c]-d[c][an]-d[bp][e]-d[e][bn];
                    if(g>=gain || x.load-in.nodes[c].demand+in.nodes[e].demand>in.capacity || y.load-in.nodes[e].demand+in.nodes[c].demand>in.capacity)continue;
                    R u=x,v=y;u.v[i]=e;v.v[j]=c;
                    if(update(u)&&update(v)){gain=g;ba=a;bb=b;ar=std::move(u);br=std::move(v);}
                }
            }
            if(ba<0)break;
            rs[ba]=std::move(ar);rs[bb]=std::move(br);clean(rs);
        }
'''+s[pos:]
s=s.replace('// CVRPTW baseline solver: Nearest-Neighbor construction with Push-Forward\n// time-window feasibility check. Approx. 240 lines, no third-party deps.','// CVRPTW regret-insertion and large-neighborhood search solver.\n// Cached schedule bounds keep insertion checks constant time.')
s=s.replace('// This is a deliberately simple baseline. Agents are expected to replace\n// or extend it with stronger metaheuristics (ALNS, SISR, Tabu, etc.).','// Retains the best complete solution, prioritizing vehicle count then distance.')
open(p,'w').write(s)
PY
make solver && for f in instances/public/*.txt; do ./cvrptw_solver "$f" src/check.txt 1 && ./tools/verify "$f" src/check.txt; done
rm -f src/check.txt
python3 feedback.py
